//@version=6
// AK MACD All-in-One — OPTION 1 preview: the 3 strategy indicators in ONE slot.
//
// Fits the TradingView free 2-indicator limit with room to spare (1 slot, 1 free).
// Trade-off vs the 2-slot layout: volume is shown as a COLORED BACKGROUND
// (green when volume > MA9) instead of real columns, because a single Pine
// indicator has only one sub-pane and MACD (~±0.001) and volume (~thousands)
// can't share a scale. The volume filter is boolean in the strategy anyway.
//
// Visual-only helper (no orders). Reproductions validated against the real
// indicators: AK MACD dots = slope coloring; SSL baseline EMA30 / Keltner 0.2.

indicator("AK MACD All-in-One", "AKM-ALL", overlay = false, max_labels_count = 200)

// --- AK MACD BB (slope-colored dots) ----------------------------------------
macdFast = input.int(12, "MACD fast", group = "AK MACD")
macdSlow = input.int(26, "MACD slow", group = "AK MACD")
macdSig  = input.int(9,  "MACD signal", group = "AK MACD")
macdLine   = ta.ema(close, macdFast) - ta.ema(close, macdSlow)
signalLine = ta.ema(macdLine, macdSig)
dotGreen = macdLine > macdLine[1]              // slope: green when rising
flipUp   = macdLine > macdLine[1] and macdLine[1] <= macdLine[2]
flipDown = macdLine < macdLine[1] and macdLine[1] >= macdLine[2]
aboveZero = macdLine > 0
belowZero = macdLine < 0

// --- SSL Hybrid baseline (EMA30, Keltner continuation blue/red/gray) ---------
baseLen = input.int(30, "Baseline length", group = "SSL Hybrid")
multy   = input.float(0.2, "Base channel multiplier", group = "SSL Hybrid")
baseline = ta.ema(close, baseLen)
rangeMa  = ta.ema(ta.tr(true), baseLen)
upperK   = baseline + rangeMa * multy
lowerK   = baseline - rangeMa * multy
isBlue = close > upperK
isRed  = close < lowerK
isGray = not isBlue and not isRed
baseColor = isBlue ? color.new(color.blue, 0) : isRed ? color.new(color.red, 0) : color.new(color.gray, 0)

// --- Volume filter (shown as background) -------------------------------------
volMaLen = input.int(9, "Volume MA length", group = "Volume")
volMa = ta.sma(volume, volMaLen)
volOk = volume > volMa

// --- Entry logic (long-only by default) -------------------------------------
trendLook = input.int(50, "Trend lookback", group = "Setup")
pullLook  = input.int(10, "Pullback lookback", group = "Setup")
allowShort = input.bool(false, "Show SELL markers", group = "Setup")
wasBull = ta.barssince(isBlue) < trendLook
pulledLong = ta.barssince(isGray or isRed) < pullLook
buyCond  = wasBull and pulledLong and close > baseline and flipUp and aboveZero and volOk
wasBear = ta.barssince(isRed) < trendLook
pulledShort = ta.barssince(isGray or isBlue) < pullLook
sellCond = allowShort and wasBear and pulledShort and close < baseline and flipDown and belowZero and volOk

// --- Visual layer ------------------------------------------------------------
// Baseline on price.
plot(baseline, "MA Baseline", color = baseColor, linewidth = 2, force_overlay = true)
// Volume filter as background of THIS pane (green tint = volume above MA9).
bgcolor(volOk ? color.new(color.teal, 80) : na, title = "Volume OK")
// AK MACD dots + signal + zero line in this pane.
dotColor = dotGreen ? color.new(color.lime, 0) : color.new(color.red, 0)
plot(macdLine, "AK MACD", color = dotColor, style = plot.style_circles, linewidth = 2)
plot(signalLine, "Signal", color = color.new(color.orange, 50))
hline(0, "Zero", color = color.new(color.gray, 50))
// Entry markers on price.
plotshape(buyCond,  title = "BUY",  style = shape.triangleup,   location = location.belowbar, color = color.lime, size = size.small, text = "BUY",  force_overlay = true)
plotshape(sellCond, title = "SELL", style = shape.triangledown, location = location.abovebar, color = color.red,  size = size.small, text = "SELL", force_overlay = true)

// --- Status table ------------------------------------------------------------
setRow(table t, int row, string k, string v) =>
    table.cell(t, 0, row, k, text_color = color.gray,  text_size = size.small, text_halign = text.align_left)
    table.cell(t, 1, row, v, text_color = color.white, text_size = size.small, text_halign = text.align_left)

var table dbg = table.new(position.top_right, 2, 5, border_width = 1, bgcolor = color.new(color.black, 20))
if barstate.islast
    setRow(dbg, 0, "baseline",   str.tostring(baseline, "#.#####"))
    setRow(dbg, 1, "base color", isBlue ? "blue" : isRed ? "red" : "gray")
    setRow(dbg, 2, "dots",       dotGreen ? "GREEN (rising)" : "RED (falling)")
    setRow(dbg, 3, "above zero", aboveZero ? "yes" : "no")
    setRow(dbg, 4, "vol ok",     volOk ? "yes (bg green)" : "no")

//@version=6
// 0rum Mirror — read-only mirror + candidate-signal emitter for 0rum.
//
// SCOPE (strict): this script NEVER places an order, never executes, never
// decides. It mirrors the 0rum DSL indicator vocabulary on the chart and
// EMITS candidate signals as a stable, versioned JSON payload. 0rum
// stays the master: validation, risk gates, idempotence, position state and
// accounting all happen Python-side (Phases 1-4). Paper only.
//
// Parity notes vs orum/dsl/indicators.py:
//   - RSI = Wilder (ta.rsi)            -> matches
//   - ATR = RMA Wilder (ta.atr)        -> matches
//   - Bollinger = population stdev     -> ta.stdev default (biased) matches
//   - EMA seed differs (ta.ema seeds recursively; 0rum seeds on SMA of the
//     first `period`): expect a small warm-up divergence that converges.
//   - regime = rolling 20-bar return, +/-0.3% -> reimplemented exactly below.

indicator("0rum Mirror", "HMIRROR", overlay = true, max_labels_count = 200)

// ----- Inputs (defaults baked to the requested 0rum config) -----------------
emaFastLen    = input.int(9,    "EMA fast")
emaMidLen     = input.int(21,   "EMA mid")
emaSlowLen    = input.int(50,   "EMA slow")
sma52Len      = input.int(52,   "SMA length (daily background filter)")
rsiLen        = input.int(14,   "RSI length")
atrLen        = input.int(14,   "ATR length")
bbLen         = input.int(20,   "Bollinger length")
bbMult        = input.float(2.0,"Bollinger stddev")
useRsiGuard   = input.bool(true,"Require RSI < overbought for BUY")
rsiOverbought = input.int(70,   "RSI overbought")
allowShort    = input.bool(false,"Emit SELL_CANDIDATE (engine is long-only)")
emitAlerts    = input.bool(true, "Emit alert() payloads (once per bar close)")
strategyId    = input.string("0rum_mirror_v1", "Strategy id (must match 0rum allowlist)")

// ----- Indicators (0rum DSL whitelist) -------------------------------------
emaFast = ta.ema(close, emaFastLen)
emaMid  = ta.ema(close, emaMidLen)
emaSlow = ta.ema(close, emaSlowLen)
// SMA 52 on the DAILY timeframe: a true "52-day" background filter regardless
// of the chart timeframe. lookahead_off so it never repaints.
sma52d  = request.security(syminfo.tickerid, "D", ta.sma(close, sma52Len), lookahead = barmerge.lookahead_off)
rsiVal  = ta.rsi(close, rsiLen)
atrVal  = ta.atr(atrLen)
bbBasis = ta.sma(close, bbLen)
bbDev   = bbMult * ta.stdev(close, bbLen)   // biased=true default -> population, matches 0rum
bbUpper = bbBasis + bbDev
bbLower = bbBasis - bbDev

// ----- 0rum rolling-return regime (EXACT parity: lookback 20, +/-0.3%) ------
regLookback = 20
regThresh   = 0.003
regRet      = (close - close[regLookback - 1]) / close[regLookback - 1]
0rumRegime = na(close[regLookback - 1]) ? "unknown" : regRet >= regThresh ? "favorable" : regRet <= -regThresh ? "unfavorable" : "neutral"

// ----- Background trend filter (SMA 52 daily) --------------------------------
bgUp = close > sma52d

// ----- Hoisted crossovers (parity rule: never call ta.cross* inside an if) ----
xUp   = ta.crossover(emaFast, emaMid)
xDown = ta.crossunder(emaFast, emaMid)
lostTrend = close < sma52d and close[1] >= sma52d[1]

// ----- Candidate events (0rum decides; this only PROPOSES) ------------------
buyCond  = xUp and bgUp and (not useRsiGuard or rsiVal < rsiOverbought)
exitCond = xDown or lostTrend
sellCond = allowShort and xDown and not bgUp

evt = buyCond ? "BUY_CANDIDATE" : exitCond ? "EXIT" : sellCond ? "SELL_CANDIDATE" : ""
hasEvt = evt != ""

// ----- Timeframe in 0rum notation ("15m","1h","1d","1w") --------------------
tf0rum = timeframe.isintraday ? (timeframe.in_seconds() % 3600 == 0 ? str.tostring(timeframe.in_seconds() / 3600) + "h" : str.tostring(timeframe.in_seconds() / 60) + "m") : timeframe.isdaily ? str.tostring(timeframe.multiplier) + "d" : timeframe.isweekly ? str.tostring(timeframe.multiplier) + "w" : timeframe.period

// ----- Stable, versioned payload for the orchestrator -------------------------
// bar_time is `time` = bar-open epoch in MILLISECONDS (matches 0rum ms canon).
// 0rum recomputes its own dedup key from (source|strategy|symbol|timeframe|
// event|bar_time), so no sig_key is sent. The extra indicator fields are NOT
// read by the validator (decision is unchanged); they are kept in `raw` purely
// to make the external_signals.jsonl audit trail readable.
barTimeStr = str.tostring(time, "#")
payload = '{"source":"tradingview","strategy":"' + strategyId + '","symbol":"' + syminfo.ticker + '","timeframe":"' + tf0rum + '","event":"' + evt + '","bar_time":' + barTimeStr + ',"price":' + str.tostring(close) + ',"version":"tv_0rum_mirror_v1","rsi":' + str.tostring(rsiVal) + ',"atr":' + str.tostring(atrVal) + ',"regime":"' + 0rumRegime + '","ema_fast":' + str.tostring(emaFast) + ',"ema_mid":' + str.tostring(emaMid) + ',"ema_slow":' + str.tostring(emaSlow) + ',"sma52d":' + str.tostring(sma52d) + '}'

// Emit only on a CONFIRMED (closed) bar -> no repaint, no intrabar signal.
if barstate.isconfirmed and hasEvt and emitAlerts
    alert(payload, alert.freq_once_per_bar_close)

// ----- Visual layer -----------------------------------------------------------
plot(emaFast, "EMA 9",   color.new(color.yellow,  0))
plot(emaMid,  "EMA 21",  color.new(color.orange,  0))
plot(emaSlow, "EMA 50",  color.new(color.fuchsia, 0))
plot(sma52d,  "SMA 52D", color.new(color.aqua,    0), linewidth = 2)
bgcolor(bgUp ? color.new(color.green, 92) : color.new(color.red, 92), title = "Background filter")

plotshape(buyCond,  title = "BUY",  style = shape.triangleup,   location = location.belowbar, color = color.lime,   size = size.small, text = "BUY")
plotshape(exitCond, title = "EXIT", style = shape.xcross,       location = location.abovebar, color = color.orange, size = size.tiny,  text = "EXIT")
plotshape(sellCond, title = "SELL", style = shape.triangledown, location = location.abovebar, color = color.red,    size = size.small, text = "SELL")

// ----- Debug table (read by MCP data_get_pine_tables to compare Pine<->Python)-
var string lastPayload = "none"
var string lastEvt     = "none"
if barstate.isconfirmed and hasEvt
    lastPayload := payload
    lastEvt     := evt

setRow(table t, int row, string k, string v) =>
    table.cell(t, 0, row, k, text_color = color.gray,  text_size = size.small, text_halign = text.align_left)
    table.cell(t, 1, row, v, text_color = color.white, text_size = size.small, text_halign = text.align_left)

var table dbg = table.new(position.top_right, 2, 14, border_width = 1, bgcolor = color.new(color.black, 20))
if barstate.islast
    setRow(dbg, 0,  "symbol/tf", syminfo.ticker + " " + tf0rum)
    setRow(dbg, 1,  "close",     str.tostring(close))
    setRow(dbg, 2,  "EMA 9",     str.tostring(emaFast, "#.##"))
    setRow(dbg, 3,  "EMA 21",    str.tostring(emaMid,  "#.##"))
    setRow(dbg, 4,  "EMA 50",    str.tostring(emaSlow, "#.##"))
    setRow(dbg, 5,  "SMA 52D",   str.tostring(sma52d,  "#.##"))
    setRow(dbg, 6,  "RSI(14)",   str.tostring(rsiVal,  "#.##"))
    setRow(dbg, 7,  "ATR(14)",   str.tostring(atrVal,  "#.##"))
    setRow(dbg, 8,  "BB mid",    str.tostring(bbBasis, "#.##"))
    setRow(dbg, 9,  "regime",    0rumRegime)
    setRow(dbg, 10, "bg filter", bgUp ? "UP (close>SMA52D)" : "DOWN")
    setRow(dbg, 11, "last evt",  lastEvt)
    setRow(dbg, 12, "strategy",  strategyId + " / tv_0rum_mirror_v1")
    setRow(dbg, 13, "payload",   lastPayload)

//@version=6
// SSL Baseline + Volume — visual combo for the AK MACD 15m strategy.
//
// PURPOSE: TradingView free plan allows only 2 indicators. The AK MACD strategy
// needs 3 (AK MACD BB + SSL Hybrid baseline + Volume MA). This single script
// merges TWO of them — the SSL Hybrid MA Baseline (on price) and Volume + MA(9)
// (in its own pane) — so they cost ONE slot. The real "AK MACD BB v 1.00" stays
// as the 2nd indicator. Net: all 3 visible within the 2-slot limit.
//
// This is a VISUAL helper (read-only, no orders, no signals). The 0rum signal
// engine is pine/ak_macd_15m.pine, separate.
//
// Fidelity:
//   - SSL Hybrid baseline = Mihkel00's "Keltner Baseline Channel": baseline MA,
//     bands = baseline ± ema(trueRange, len) * mult, colored blue (close>upper),
//     red (close<lower), gray (in between = pullback). Reproduced exactly.
//     User config from chart title: baseline EMA, length 30.
//   - Volume = columns colored up/down + SMA(9) MA line in white (TradingView's
//     built-in Volume MA is an SMA; user set length 9, color white).

indicator("SSL Baseline + Volume", "SSLVOL", overlay = false, max_labels_count = 50)

// ----- SSL Hybrid MA Baseline (Mihkel00 Keltner Baseline Channel) ------------
baseLen   = input.int(30,    "Baseline length",   group = "SSL Hybrid")
baseType  = input.string("EMA", "Baseline type",  options = ["EMA", "SMA", "WMA", "HMA"], group = "SSL Hybrid")
useTR     = input.bool(true,  "Use true range for channel", group = "SSL Hybrid")
multy     = input.float(0.2,  "Base channel multiplier",    group = "SSL Hybrid")

baseline = baseType == "SMA" ? ta.sma(close, baseLen)
         : baseType == "WMA" ? ta.wma(close, baseLen)
         : baseType == "HMA" ? ta.hma(close, baseLen)
         :                     ta.ema(close, baseLen)

rangeRaw = useTR ? ta.tr(true) : high - low
rangeMa  = ta.ema(rangeRaw, baseLen)
upperK   = baseline + rangeMa * multy
lowerK   = baseline - rangeMa * multy

isBlue = close > upperK
isRed  = close < lowerK
isGray = not isBlue and not isRed
baseColor = isBlue ? color.new(color.blue, 0) : isRed ? color.new(color.red, 0) : color.new(color.gray, 0)
baseColorStr = isBlue ? "blue" : isRed ? "red" : "gray"

// Baseline drawn on the PRICE chart.
plot(baseline, "MA Baseline", color = baseColor, linewidth = 2, force_overlay = true)

// ----- Volume + MA(9) (this script's own pane) -------------------------------
volMaLen = input.int(9, "Volume MA length", group = "Volume")
volUp    = close >= open
volColor = volUp ? color.new(color.teal, 50) : color.new(color.red, 50)
plot(volume, "Volume", color = volColor, style = plot.style_columns)

volMa = ta.sma(volume, volMaLen)
plot(volMa, "Volume MA", color = color.new(color.white, 0), linewidth = 2)

volOk = volume > volMa

// ----- Small status table (readable via MCP data_get_pine_tables) ------------
setRow(table t, int row, string k, string v) =>
    table.cell(t, 0, row, k, text_color = color.gray,  text_size = size.small, text_halign = text.align_left)
    table.cell(t, 1, row, v, text_color = color.white, text_size = size.small, text_halign = text.align_left)

var table dbg = table.new(position.top_right, 2, 4, border_width = 1, bgcolor = color.new(color.black, 20))
if barstate.islast
    setRow(dbg, 0, "baseline",   str.tostring(baseline, "#.#####"))
    setRow(dbg, 1, "base color", baseColorStr)
    setRow(dbg, 2, "vol/volMA",  str.tostring(volume / volMa, "#.##"))
    setRow(dbg, 3, "vol ok",     volOk ? "yes" : "no")

